package org.apache.commons.lang;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_40_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Test case where the bug manifests
        // The bug is that containsIgnoreCase uses toUpperCase which can cause issues with certain locales
        // For example, the Turkish locale has different uppercase rules for 'i'
        String str = "title";
        String searchStr = "I"; // English uppercase i
        assertFalse(StringUtils.containsIgnoreCase(str, searchStr));
    }
}

